static int check(int ok,const char *name){printf("%s UI %s\n",ok?"PASS":"FAIL",name);return ok;}
static int mode(int width,int height,int planar){ULONG id=INVALID_ID;struct DimensionInfo dims;struct DisplayInfo display;struct NDScreenModePreset prefs;unsigned char b[62];FILE *f;int found=0;while((id=NextDisplayInfo(id))!=INVALID_ID){if(ModeNotAvailable(id)||!GetDisplayInfoData(NULL,(UBYTE *)&dims,sizeof(dims),DTAG_DIMS,id)||!GetDisplayInfoData(NULL,(UBYTE *)&display,sizeof(display),DTAG_DISP,id)||display.NotAvailable||!(display.PropertyFlags&DIPF_IS_WB))continue;if(dims.Nominal.MaxX-dims.Nominal.MinX+1==width&&dims.Nominal.MaxY-dims.Nominal.MinY+1==height&&((planar&&dims.MaxDepth<=8)||(!planar&&dims.MaxDepth>=16))){memset(&prefs,0,sizeof(prefs));prefs.display_id=id;prefs.width=width;prefs.height=height;prefs.depth=planar?4:16;prefs.control=1;found=1;break;}}if(!found||nd_scrmode_encode(&prefs,b,sizeof(b))!=sizeof(b))return 0;f=fopen("QATests:mode.prefs","wb");if(!f)return 0;found=fwrite(b,1,sizeof(b),f)==sizeof(b);if(fclose(f)||!found)return 0;if(SystemTags("SYS:Prefs/ScreenMode FROM QATests:mode.prefs USE",TAG_DONE)!=0)return 0;Delay(50);return 1;}
static int screenshot(struct Screen *s,const char *name){FILE *f;UBYTE *row;ULONG colours[256*3];int x,y,rtg=NDGlassCyberGfxBase&&nd_glass_bitmap(s->RastPort.BitMap);row=AllocVec(s->Width*3UL,MEMF_PUBLIC);if(!row)return 0;f=fopen(name,"wb");if(!f){FreeVec(row);return 0;}fprintf(f,"P6\n%d %d\n255\n",s->Width,s->Height);if(!rtg)GetRGB32(s->ViewPort.ColorMap,0,1UL<<s->RastPort.BitMap->Depth,colours);for(y=0;y<s->Height;++y){if(rtg)nd_glass_rgb_line(row,s->Width,&s->RastPort,y);else for(x=0;x<s->Width;++x){LONG pen=ReadPixel(&s->RastPort,x,y);row[x*3]=colours[pen*3]>>24;row[x*3+1]=colours[pen*3+1]>>24;row[x*3+2]=colours[pen*3+2]>>24;}if(fwrite(row,3,s->Width,f)!=(size_t)s->Width){fclose(f);FreeVec(row);return 0;}}fclose(f);FreeVec(row);return 1;}
static int escape(const char *title){struct Window *w=qa_window(title);if(!w)return 0;ActivateWindow(w);Delay(5);return qa_key(0x45,0)&&qa_gone(title);}
static int page(const char *args,const char *title,int photo){char command[128];struct Window *w;sprintf(command,"QATests:Dock/NovaDockPrefs %s",args);if(!qa_start(command)||(w=qa_wait_window("NovaDock Preferences"))==NULL)return check(0,title);printf("UI_TITLE %s\n",w->Title);printf("UI_WINDOW %s %dx%d font=%dx%d\n",title,w->Width,w->Height,w->RPort->Font->tf_XSize,w->RPort->Font->tf_YSize);if(!check(qa_bounds(w),title))return 0;if(photo&&!screenshot(w->WScreen,photo==1?"QATests:appearance.ppm":"QATests:about.ppm"))return 0;return check(escape("NovaDock Preferences"),"physical Escape cancels Preferences");}
static int report(void){struct Window *w;struct Gadget *g;int i;static const char *next[]={"NovaDock Support Report - description","NovaDock Support Report - what happened","NovaDock Support Report - system / save"};if(!qa_start("QATests:Dock/SupportReport FORM")||(w=qa_wait_window("NovaDock report - recording"))==NULL||!qa_bounds(w)||!qa_post(w,IDCMP_GADGETUP,0,2))return check(0,"start guided report");if(!(w=qa_wait_window("NovaDock Support Report - prepare"))||!qa_bounds(w)||!qa_post(w,IDCMP_GADGETUP,0,101))return 0;if(!(w=qa_wait_window("NovaDock Support Report - details"))||!qa_bounds(w))return 0;
 g=qa_gadget(w,1);if(!g||!ActivateGadget(g,w,NULL))return 0;Delay(5);if(!qa_key(0x10,0)||strcmp(((struct StringInfo *)g->SpecialInfo)->Buffer,"q"))return check(0,"physical typing into Name");
 if(!qa_key(0x42,0))return 0;g=qa_gadget(w,2);if(!qa_key(0x11,0)||strcmp(((struct StringInfo *)g->SpecialInfo)->Buffer,"w"))return check(0,"Tab moves to Email");
 if(!qa_key(0x42,IEQUALIFIER_LSHIFT))return 0;g=qa_gadget(w,1);if(!qa_key(0x12,0)||strcmp(((struct StringInfo *)g->SpecialInfo)->Buffer,"qe"))return check(0,"Shift-Tab returns to Name");
 if(!qa_key(0x44,0)||!qa_window("NovaDock Support Report - details"))return check(0,"Enter accepts a field without saving report");check(1,"physical typing, Tab, Shift-Tab and Enter");g=qa_gadget(w,3);GT_SetGadgetAttrs(g,w,NULL,GTST_String,(ULONG)"Long title: hover over the dock, add a plugin, then reopen Preferences",TAG_DONE);Delay(8);
 for(i=0;i<3;++i){w=qa_window("NovaDock Support Report");if(!w||!qa_post(w,IDCMP_GADGETUP,0,101))return check(0,"advance report page");w=qa_wait_window(next[i]);if(!w||!qa_bounds(w))return check(0,next[i]);}
 if(!screenshot(w->WScreen,"QATests:report.ppm"))return 0;return check(escape("NovaDock Support Report"),"physical Escape cancels report without saving");}
int main(int argc,char **argv){struct Screen *s=NULL;struct TextAttr font_attr={"topaz.font",9,0,0},*original_attr=NULL;struct TextFont *font=NULL,*original_font=NULL;FILE *f;int planar=argc>1&&!strcmp(argv[1],"PLANAR"),large=argc>1&&!strcmp(argv[1],"LARGE"),result=10;unsigned int i;LONG control_result;struct NDDiagnosticsSnapshot d;if(!qa_init())return 20;printf("UI_BUILD %s variant=%s\n",ND_BUILD_ID,argc>1?argv[1]:"RTG");if(!check(mode(large?800:640,planar?256:large?600:480,planar),"requested native display mode"))goto done;s=LockPubScreen("Workbench");if(!s)goto done;NDGlassCyberGfxBase=OpenLibrary("cybergraphics.library",40);printf("UI_SCREEN %dx%d depth=%lu\n",s->Width,s->Height,GetBitMapAttr(s->RastPort.BitMap,BMA_DEPTH));if(!check(s->Width==(large?800:640)&&s->Height==(planar?256:large?600:480)&&(planar?GetBitMapAttr(s->RastPort.BitMap,BMA_DEPTH)<=8:GetBitMapAttr(s->RastPort.BitMap,BMA_DEPTH)>=16),"actual screen dimensions and depth"))goto done;
 if(large){font=OpenFont(&font_attr);if(!font)goto done;original_attr=s->Font;original_font=s->RastPort.Font;s->Font=&font_attr;SetFont(&s->RastPort,font);printf("UI_LARGE_FONT %dx%d\n",font->tf_XSize,font->tf_YSize);}
 SystemTags("MakeDir RAM:UIEnv RAM:UIEnv/NovaDock RAM:UIArc",TAG_DONE);SystemTags("Assign ENV: RAM:UIEnv",TAG_DONE);SystemTags("Assign ENVARC: RAM:UIArc",TAG_DONE);SystemTags("Assign NovaDock: QATests:Dock",TAG_DONE);f=fopen("ENV:NovaDock/novadock.cfg","w");if(!f)goto done;fputs("SIDE=BOTTOM\nDRAG_BAR=YES\nAUTO_HIDE=NO\nREMOVABLE_MEDIA=NO\nRUNNING_APPS=NO\nRUNNING_SECTION=NO\nDRAWER=A very long drawer title 123456|SYS:|SYS:Disk|ON|AUTO\nPLUGIN=CPU|Plugins/Activity|CPU|METER|ON\n",f);fclose(f);if(!qa_start("QATests:Dock/NovaDock"))goto done;for(i=0;i<120;++i){control_result=nd_control_diagnostics(&d);if(control_result==ND_CONTROL_OK&&d.online_count==1)break;if(!(i%10))printf("UI_WAIT i=%u rc=%ld online=%u\n",i,control_result,d.online_count);Delay(10);}printf("UI_DOCK waited=%u tiles=%lu online=%u count=%u\n",i,d.tile_count,d.online_count,d.plugin_count);if(i==120)goto done;
 if(!page("","NovaDock Preferences - General",0)||!page("PAGE=APPEARANCE","NovaDock Preferences - Appearance",1)||!page("PAGE=ITEMS","NovaDock Preferences - Organize",0)||!page("PAGE=PLUGINS","NovaDock Preferences - Plugins",0)||!page("PAGE=SUPPORT","NovaDock Preferences - Support",0)||!page("PAGE=UPDATE","NovaDock Preferences - Update",0)||!page("PAGE=ABOUT","NovaDock Preferences - About",2)||!report())goto done;result=0;
 done:if(s)screenshot(s,"QATests:final.ppm");qa_stop();if(original_attr&&s){s->Font=original_attr;SetFont(&s->RastPort,original_font);}if(font)CloseFont(font);if(NDGlassCyberGfxBase)CloseLibrary(NDGlassCyberGfxBase);if(s)UnlockPubScreen(NULL,s);qa_finish();printf("%s UI MATRIX\n",result?"FAIL":"PASS");return result;}
